pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 warpTime) public {
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        vm.roll(blockNumber);

        address sender = address(0xABCD);
        vm.deal(sender, 10 ether);

        bool ok;
        vm.prank(sender);
        (ok,) = address(c).call{value: 10 ether}("");

        if (ok) {
            assertTrue(c.pastBlockTime() == block.timestamp);
        }
    }
}
